body.script:
/*
 * Astra launcher.
 *
 * Opened directly (as an SVG document), this finds a reachable Astra
 * host and sends the browser to its lite player. The player, the API
 * and everything heavy live on that host — this file carries none of
 * it, so there is nothing here to copy but a redirect.
 *
 * A host passes only when GET /api/ping?n=<nonce> answers with CORS and
 * echoes the nonce back: a captive/block page answers 200 but can do
 * neither. Where CORS isn't configured, it falls back to a plain
 * reachability check and lets the player verify once it loads.
 */
(function () {
  var msg = document.getElementById("msg");
  var sp = document.getElementById("sp");
  var CACHE = "astra.host";
  var PATH = "/l";               // lite player path on the host
  var PROBE_MS = 4500;
  var BAKED = ["https://your-astra-host.example"]; // edit me / apis.json

  function say(t) { try { msg.textContent = t; } catch (e) {} }
  function norm(h) {
    var s = ("" + h).trim().replace(/\/+$/, "");
    return /^https?:\/\//.test(s) ? s : "https://" + s;
  }
  function remembered() {
    try { return localStorage.getItem(CACHE) || ""; } catch (e) { return ""; }
  }
  function remember(h) {
    try { localStorage.setItem(CACHE, h); } catch (e) {}
  }

  // apis.json sits next to this SVG in the same repo, so hosts change
  // with a commit — no rebuild. Falls back to the baked list.
  function loadHosts() {
    var here = (document.currentScript && document.currentScript.src) || location.href;
    var url = here.replace(/[^/]*(?:[?#].*)?$/, "") + "apis.json";
    return fetch(url, { cache: "no-store" })
      .then(function (r) { return r.ok ? r.json() : null; })
      .then(function (j) {
        var list = (j && Array.isArray(j.hosts)) ? j.hosts : [];
        return list.length ? list : BAKED;
      })
      .catch(function () { return BAKED; });
  }

  function withTimeout(p, ms) {
    return new Promise(function (resolve) {
      var done = false;
      var t = setTimeout(function () { if (!done) { done = true; resolve(false); } }, ms);
      p.then(function (v) { if (!done) { done = true; clearTimeout(t); resolve(v); } },
             function () { if (!done) { done = true; clearTimeout(t); resolve(false); } });
    });
  }

  // Strong check: CORS + nonce echo. Returns true only for real Astra.
  function pingStrict(host, nonce) {
    return withTimeout(
      fetch(host + "/api/ping?n=" + nonce, { cache: "no-store", mode: "cors" })
        .then(function (r) { return r.ok ? r.json() : null; })
        .then(function (j) { return !!(j && j.ok === true && j.n === nonce); }),
      PROBE_MS
    );
  }
  // Weak fallback where CORS isn't set up: just reachable. The player
  // re-checks same-origin and moves on if it landed on a block page.
  function pingLoose(host) {
    return withTimeout(
      fetch(host + "/api/ping", { cache: "no-store", mode: "no-cors" })
        .then(function () { return true; }),
      PROBE_MS
    );
  }

  function go(host) {
    remember(host);
    say("Opening…");
    location.replace(host + PATH);
  }

  // Race all hosts; first to pass wins. Try the strong check across the
  // whole list first, then the loose one.
  function firstThatPasses(hosts, check) {
    return new Promise(function (resolve) {
      var left = hosts.length, won = false;
      if (!left) return resolve(null);
      hosts.forEach(function (h) {
        check(h).then(function (ok) {
          if (won) return;
          if (ok) { won = true; resolve(h); return; }
          if (--left === 0) resolve(null);
        });
      });
    });
  }

  say("Finding the best server…");
  loadHosts().then(function (raw) {
    var seen = {}, hosts = [];
    [remembered()].concat(raw).forEach(function (h) {
      if (!h) return;
      var n = norm(h);
      if (!seen[n]) { seen[n] = 1; hosts.push(n); }
    });
    var nonce = Math.random().toString(36).slice(2) + Date.now().toString(36);
    firstThatPasses(hosts, function (h) { return pingStrict(h, nonce); })
      .then(function (hit) {
        if (hit) return go(hit);
        return firstThatPasses(hosts, pingLoose).then(function (h2) {
          if (h2) return go(h2);
          sp.style.display = "none";
          msg.className = "msg err";
          say("Couldn't reach Astra right now. Check your connection and try again.");
        });
      });
  });
})();
